class TextScramble{constructor(e){this.el=e,this.chars="!<>-_\\/[]{}#$%^&*+=~`|",this.originalText=e.textContent,this.frame=0,this.queue=[],this.resolve=null,this.frameRequest=null}setText(e){const t=this.el.textContent,r=Math.max(t.length,e.length),s=new Promise(e=>this.resolve=e);this.queue=[];for(let s=0;s<r;s++){const r=t[s]||"",h=e[s]||"",a=Math.floor(30*Math.random()),o=a+Math.floor(30*Math.random());this.queue.push({from:r,to:h,start:a,end:o})}return cancelAnimationFrame(this.frameRequest),this.frame=0,this.update(),s}update(){let e="",t=0;for(let r=0,s=this.queue.length;r<s;r++){let{from:s,to:h,start:a,end:o,char:n}=this.queue[r];this.frame>=o?(t++,e+=h):this.frame>=a?((!n||Math.random()<.28)&&(n=this.chars[Math.floor(Math.random()*this.chars.length)],this.queue[r].char=n),e+=`<span style="color:var(--color-primary);opacity:0.6;">${n}</span>`):e+=s}this.el.innerHTML=e,t===this.queue.length?this.resolve():(this.frameRequest=requestAnimationFrame(()=>this.update()),this.frame++)}}document.addEventListener("DOMContentLoaded",()=>{if(window.matchMedia("(prefers-reduced-motion: reduce)").matches)return;const e=document.querySelector(".hero h1");if(!e)return;if(e.querySelector(".hero-word"))return;const t=e.textContent,r=new TextScramble(e);setTimeout(()=>{r.setText(t)},400)});